mapper.select:
SELECT b.sha256 FROM ja_attachment_blob b
WHERE NOT EXISTS(SELECT 1 FROM ja_attachment a WHERE a.blob_sha256=b.sha256 AND a.status IN ('DRAFT','BOUND'))
ORDER BY b.created_at_ms,b.sha256 LIMIT #{limit}

mapper.update:
UPDATE ja_conversation_title_generation SET result=#{result},input_tokens=#{inputTokens},output_tokens=#{outputTokens},
total_tokens=#{totalTokens},failure_code=#{failureCode},completed_at_ms=#{completedAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE generation_id=#{generationId} AND result IS NULL
